import{_ as a,o as n,c as t,ag as s}from"./chunks/framework.D9ghT4bC.js";const _=JSON.parse('{"title":"存档与瞬态","description":"","frontmatter":{},"headers":[],"relativePath":"zh/Developers/Saved-games-and-transients.md","filePath":"zh/Developers/Saved-games-and-transients.md"}'),i={name:"zh/Developers/Saved-games-and-transients.md"};function p(m,e,r,o,u,l){return n(),t("div",null,[...e[0]||(e[0]=[s('<h1 id="存档与瞬态" tabindex="-1">存档与瞬态 <a class="header-anchor" href="#存档与瞬态" aria-label="Permalink to &quot;存档与瞬态&quot;">​</a></h1><p>Unciv 是一款万物互联的游戏。例如，每个地图单位都属于一个<em>文明</em>，位于一个<em>地块</em>上，可以有几个<em>晋升</em>，并&quot;继承&quot;自一个<em>基础单位</em>。</p><p>保存游戏状态时，我们希望它尽可能小——所以把保存的信息限制到最低限度。我们保存名称而不是指针，任何可以重新计算的东西都不保存。</p><p>但在运行时，我们<em>需要</em>这些链接以保证性能——如果能在对象上保存引用，何必每次都做查找？</p><p>因此，类在序列化时被<em>冻干</em>，在运行时再<em>补水</em>。由于这些字段在 Kotlin 中标记为 @Transient，我们把补水函数命名为 <code>setTransients</code>。</p><p>以地图单位为例。如何计算该单位的 uniques？它们可能来自多个地方：</p><ul><li>基础单位的 uniques</li><li>晋升</li><li>全文明范围的 uniques</li></ul><p>所以从存档中我们得到文明名、单位名和晋升名；运行时我们想要的是对文明、基础单位和晋升的引用。</p><p>我们可以通过在游戏中查找文明、在规则集中查找单位和晋升来得到它们。</p><p>文明本身——一个游戏对象——引用国家——一个规则集对象，这是另一个链接。基础单位引用单位类型，又是一个链接。</p><p>国家、基础单位和晋升都包含 <em>uniques</em>——以字符串保存。为了性能，运行时它们也被保存为 Unique 实例——包含 unique 类型、参数、条件等。</p><p>除了每个规则集对象保留一份&quot;已补水&quot;的 uniques 列表之外，单位的 uniques 不经常变化——所以我们还可以再加<em>一层</em>缓存：保存单位的所有 uniques，并在每次变化时重建它。</p><p>所有这一切对性能都<em>至关重要</em>——Unciv 的目标是在老破小设备上也能跑，而即使是哈希查找，在频繁执行时也很昂贵，更不用说解析 Unique 所需的 Regex 了！</p>',13)])])}const c=a(i,[["render",p]]);export{_ as __pageData,c as default};
